package com.CodeSphere.backend.controller;
import com.CodeSphere.backend.security.CustomUserDetails; import com.CodeSphere.backend.service.NotificationService; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notifications") @RequiredArgsConstructor public class NotificationController { private final NotificationService service; private Long user(){Object p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(p instanceof CustomUserDetails u)return u.getId();throw new IllegalStateException("Authenticated user details are unavailable.");} @GetMapping public ResponseEntity<?> mine(){return ResponseEntity.ok(service.mine(user()));} @PutMapping("/{id}/read") public ResponseEntity<Void> read(@PathVariable Long id){service.markRead(user(),id);return ResponseEntity.noContent().build();} @PutMapping("/read-all") public ResponseEntity<Void> readAll(){service.markAllRead(user());return ResponseEntity.noContent().build();}}
